{"code": "from jinja2 import Environment, filters

# Create an Environment instance with a custom filter
env = Environment(loader=Environment())

# Define the list of dictionaries
data = [{'price': 10}, {'price': 20}, {'price': 30}]

# Define a custom filter to calculate the sum of 'price' values
@env.filter
def sum_prices(prices):
    return sum(price['price'] for price in prices)

# Render the template with the data and the custom filter
result = env.from_string(data).render(price=sum_prices)

# Output the result
result"}

